import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/newNex10Dev_familiarizeToolInterface1.D5U5enU5.png",s="data:image/png;base64,",i="/assets/newNex10Dev_familiarizeToolInterface3.CPfNvhdS.png",p="/assets/neoExtension_05.Ch_2m0OB.png",h=JSON.parse('{"title":"熟悉工具界面","description":"","frontmatter":{},"headers":[],"relativePath":"v1/扩展代码管理/熟悉工具界面.md","filePath":"v1/扩展代码管理/熟悉工具界面.md"}'),d={name:"v1/扩展代码管理/熟悉工具界面.md"};function E(l,t,A,g,c,m){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="熟悉工具界面" tabindex="-1">熟悉工具界面 <a class="header-anchor" href="#熟悉工具界面" aria-label="Permalink to &quot;熟悉工具界面&quot;">​</a></h1><p>遵循以下步骤，打开新版 NEX 开发工具：</p><ol><li><p>登录销售易系统。</p></li><li><p>打开目标对象的新建或编辑页。</p></li><li><p>打开开发者工具（F12 或者鼠标右击页面的任意位置并在快捷菜单中单击<strong>检查</strong>），然后切换到 <strong>Neo Extension</strong> 页签。 <img src="'+n+'" alt=""></p><table tabindex="0"><thead><tr><th>图中序号</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>切换工具版本。<br>进入工具后，默认为基于新版 Neo UI 的 NEX 扩展界面。如果未升级到新版 Neo UI，可单击 <img src="'+s+'" alt=""> 切换为 RPA 模式，对旧版本的代码进行查看或编辑。<br>目前已不建议使用 RPA 进行页面扩展开发，本文档只介绍 Neo UI 的扩展开发方法。关于 NEX 与 RPA 区别请参考<a href="https://ui.neocrm.com/web/#/extension/ext_introduce/nex-rpa" target="_blank" rel="noreferrer">NEX 与 RPA 的区别</a>，关于 RPA 开发的相关信息请参考 <a href="https://doc.xiaoshouyi.com/?sso-domain=login.xiaoshouyi.com#/proMan/workplaceDetail?url=%2F%2Fconcepts%2F%E9%94%80%E5%94%AE%E6%98%93CRM_PaaS_%E5%B9%B3%E5%8F%B0_NEX%E9%A1%B5%E9%9D%A2%E6%89%A9%E5%B1%95%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C_V2108.01_%E7%AC%AC%E4%B8%80%E7%AB%A0_nex_%E6%89%A9%E5%B1%95%E5%BC%80%E5%8F%91%E7%AE%80%E4%BB%8B.html&amp;id=1115&amp;dir=output_1721721381928&amp;time=1727075020737&amp;proId=779&amp;checkStat=undefined" target="_blank" rel="noreferrer">NEX页面扩展开发手册（原RPA部分）</a>（<strong>文档中心</strong> &gt; <strong>产品手册</strong> &gt; <strong>PaaS 平台</strong> &gt; **NEX页面扩展开发手册（原RPA部分）**文档）。<br></td></tr><tr><td>2</td><td>展示当前系统（租户）中已创建的所有扩展代码。<br>· 扩展代码名称的命名规则为：业务对象 API 名称.页面类型.nex，可以通过代码名称判断出扩展代码属于哪个对象。<br>· 将鼠标悬浮于扩展代码名称后面的发布状态上，可以选择对该扩展代码进行删除、禁用或编辑操作。<img src="'+i+'" alt=""></td></tr><tr><td>3</td><td>进入工具后，默认展示当前所在页面的扩展代码。如果当前页面无扩展代码，此处会显示<strong>新建</strong>按钮，单击<strong>新建</strong>可创建该页面的扩展代码。<br>在 2 号区域中选择其他扩展点进行编辑时，此处会展示当前正在编辑的扩展代码名称。<br></td></tr><tr><td>4</td><td>· 展示当前正在编辑的扩展代码名称、当前登录的开发者姓名以及当前时间。<br>· 一个扩展代码可以包含多个版本，但同时只能发布一个版本，可以根据需要切换扩展代码的版本。<img src="'+p+'" alt=""></td></tr><tr><td>5</td><td>按钮栏。<br>· 预览单击<strong>预览</strong>，即可在下一次打开页面时试运行当前的扩展规则。预览仅对当前浏览器的下一次操作有效，且预览前会对代码的合法性进行检查，若存在语法错误，将提示相应的错误信息。<br>· 编辑可以在 6 号区域修改代码，已发布的代码需要先禁用才能编辑。<br>· 保存将当前编辑代码存储到服务端。<br>· 发布扩展代码对所有用户生效，已发布的代码可禁用，禁用后将恢复编辑功能，且不再对线上用户生效。<br>· 复制发布状态的扩展代码可以通过<strong>复制</strong>按钮创建一个新的版本，旧版本仍然保持生效直至新版本被启用。</td></tr><tr><td>6</td><td>代码编写区，创建扩展代码时会自动生成代码框架。<br>关于扩展代码的编写方法（代码结构、扩展工具函数、扩展示例）的介绍，请参考 <a href="https://ui.neocrm.com/web/#/extension" target="_blank" rel="noreferrer">Neo 扩展开发文档</a>。<br></td></tr><tr><td>7</td><td>单击后可查看 <a href="https://ui.neocrm.com/web/#/extension" target="_blank" rel="noreferrer">Neo 扩展开发文档</a>。</td></tr></tbody></table></li></ol>',3)])])}const b=e(d,[["render",E]]);export{h as __pageData,b as default};
